  ('Q_20261106_08_05', 'PG', 'Bahasa Inggris SMP 8', 'Your teacher is explaining the lesson. You should ....', 'none', '', '["Sleep", "Talk loudly", "Listen carefully", "Play"]'::jsonb, '[]'::jsonb, 'Listen carefully', 10, 'Sesuai kunci jawaban.'),
