  ('Q_20261115_08_30', 'PG', 'Prakarya 8', 'Sebuah kerajinan membutuhkan 10 cangkang telur, tetapi Dina dapat menyiapkan 20 cangkang untuk mengantisipasi jika ada cangkang yang ternyata tidak layak pakai. Tindakan Dina sesuai dengan kriteria....', 'none', '', '["mudah didapat", "ketersediaan jumlah", "tidak mudah busuk", "mampu diolah"]'::jsonb, '[]'::jsonb, 'ketersediaan jumlah', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_31', 'PG', 'Prakarya 8', 'Perhatikan gambar desain vas bunga berikut!<br>Desain vas bunga tersebut dibuat tampak dari…', 'image', './assets/soal/soal-0042.jpg', '["depan", "atas", "samping", "bawah"]'::jsonb, '[]'::jsonb, 'samping', 10, 'Sesuai kunci jawaban.'),
