  ('Q_20261117_08_25', 'PG', 'Bahasa Indonesia SMP 8', 'Tujuan penulisan teks tersebut adalah ....<br>Teks 6 untuk soal nomor 26–30', 'image', './assets/soal/soal-0044.jpg', '["Menghibur pembaca dengan kisah lebah", "Mengajak pembaca memelihara lebah", "Memberikan informasi faktual tentang lebah", "Menjelaskan langkah membuat sarang lebah"]'::jsonb, '[]'::jsonb, 'Memberikan informasi faktual tentang lebah', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_26', 'PG', 'Bahasa Indonesia SMP 8', 'Pesan utama iklan layanan masyarakat tersebut adalah ....', 'none', '', '["Mengajak siswa membeli perlengkapan sekolah", "Mengajak siswa menghentikan tindakan perundungan", "Mengajak siswa mengikuti perlombaan", "Mengajak siswa belajar lebih lama"]'::jsonb, '[]'::jsonb, 'Mengajak siswa menghentikan tindakan perundungan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_27', 'PG', 'Bahasa Indonesia SMP 8', 'Kalimat yang paling tepat menunjukkan ajakan dalam iklan tersebut adalah ....', 'none', '', '["Sekolah Aman, Belajar Nyaman", "Hargai teman, jangan menyakiti.", "Stop Perundungan!", "Belajar di sekolah setiap hari."]'::jsonb, '[]'::jsonb, 'Stop Perundungan!', 10, 'Sesuai kunci jawaban.'),
