  ('Q_20261117_08_32', 'PG', 'Bahasa Indonesia SMP 8', 'Salah satu ciri utama teks LHO adalah ....', 'none', '', '["Bersifat objektif dan berdasarkan fakta", "Berisi pendapat pribadi tanpa bukti", "Mengandung banyak peristiwa khayalan", "Selalu menggunakan bahasa percakapan"]'::jsonb, '[]'::jsonb, 'Bersifat objektif dan berdasarkan fakta', 10, 'Sesuai kunci jawaban.'),
