  ('Q_20261117_08_34', 'PG', 'Bahasa Indonesia SMP 8', 'Bagian teks LHO yang menjelaskan ciri-ciri atau bagian-bagian objek disebut ....', 'none', '', '["Deskripsi bagian", "Orientasi", "Komplikasi", "Resolusi"]'::jsonb, '[]'::jsonb, 'Deskripsi bagian', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_35', 'PG', 'Bahasa Indonesia SMP 8', 'Berikut ini yang merupakan kalimat fakta adalah ....', 'none', '', '["Bunga mawar adalah bunga paling indah di dunia.", "Menurut saya, kucing merupakan hewan paling lucu.", "Lebah memiliki tiga pasang kaki.", "Pantai itu sangat menakjubkan."]'::jsonb, '[]'::jsonb, 'Lebah memiliki tiga pasang kaki.', 10, 'Sesuai kunci jawaban.'),
