  ('Q_20261117_08_41', 'PG', 'Bahasa Indonesia SMP 8', 'Slogan adalah ....', 'none', '', '["Kalimat singkat, menarik, dan mudah diingat yang berisi pesan tertentu", "Teks panjang yang berisi laporan penelitian", "Cerita yang mengandung unsur khayalan", "Kalimat yang berisi petunjuk penggunaan alat"]'::jsonb, '[]'::jsonb, 'Kalimat singkat, menarik, dan mudah diingat yang berisi pesan tertentu', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_42', 'PG', 'Bahasa Indonesia SMP 8', 'Berikut ini yang merupakan contoh slogan pendidikan adalah ....', 'none', '', '["Murah, cepat, dan berkualitas!", "Rajin Membaca, Luas Wawasan!", "Nikmati Liburan Bersama Kami!", "Belanja Hemat Setiap Hari!"]'::jsonb, '[]'::jsonb, 'Rajin Membaca, Luas Wawasan!', 10, 'Sesuai kunci jawaban.'),
